function() {
  function generateUID() {
    return Math.floor(Math.random() * 9e12) + 1e12;
  }
  var cookieName = 'br_uid_2';
  var cookieMatch = document.cookie.match('(^|;)\\s*' + cookieName + '\\s*=\\s*([^;]+)');
  var cookieValue = cookieMatch ? cookieMatch.pop() : null;
  if (!cookieValue) {
    var uid = generateUID();
    var timestamp = Math.floor(Date.now() / 1000);
    cookieValue = 'uid=' + uid + ':v=1:ts=' + timestamp + ':hc=1';
    document.cookie = cookieName + '=' + cookieValue + '; path=/; expires=Fri, 31 Dec 9999 23:59:59 GMT';
  }
  return cookieValue;
}

